// 回书接取与报告的永久来源用独立表；JSON与检查点同序，旧Task和去程文书不增加字段。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "task_message_return_state.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/tasks/task_source_projection.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class A>Status result(A& a,TaskMessageReturnResult& r){a.field("result_id",r.result_id);a.field("request_actor_id",r.request_actor_id);a.field("command_kind",r.command_kind);a.field("request_sequence",r.request_sequence);a.field("result_revision",r.result_revision);a.field("from_tick",r.from_tick);return a.field("result_tick",r.result_tick);}
template<class A>Status start(A& a,TaskMessageReturnStart& s){if(s.context.kind||s.context.encounter_id||s.context.input_error)return a.reject("UnsupportedTaskMessageReturnContext");a.field("fact_id",s.fact_id);a.field("task_id",s.task_id);a.field("offer_id",s.offer_id);a.field("policy_id",s.policy_id);a.field("handoff_fact_id",s.handoff_fact_id);a.field("action_id",s.action_id);a.field("carrier_actor_id",s.carrier_actor_id);a.field("recipient_actor_id",s.recipient_actor_id);a.field("sender_actor_id",s.sender_actor_id);a.field("reply_item_id",s.reply_item_id);a.field("carrier_inventory_id",s.carrier_inventory_id);a.field("session_id",s.session_id);a.field("dialogue_id",s.dialogue_id);a.field("node_id",s.node_id);a.object("context",[&](auto& c){c.field("place_id",s.context.place_id);c.field("provider_actor_id",s.context.provider_actor_id);return c.field("role_id",s.context.role_id);});a.field("started_tick",s.started_tick);return a.optional("actual_result",s.actual_result,[](auto& c,auto& v){return result(c,v);});}
template<class A>Status collection(A& a,TaskMessageReturnCollection& s){a.field("fact_id",s.fact_id);a.field("start_fact_id",s.start_fact_id);a.field("task_id",s.task_id);a.field("action_id",s.action_id);a.field("reply_lot_id",s.reply_lot_id);a.field("reason",s.reason);a.field("tick",s.tick);a.field("success",s.success);return a.optional("actual_result",s.actual_result,[](auto& c,auto& v){return result(c,v);});}
template<class A>Status delivery(A& a,TaskMessageReturnDelivery& s){a.field("fact_id",s.fact_id);a.field("task_id",s.task_id);a.field("collection_fact_id",s.collection_fact_id);a.field("report_start_fact_id",s.report_start_fact_id);a.field("source_action_id",s.source_action_id);a.field("report_fact_id",s.report_fact_id);a.field("settlement_id",s.settlement_id);a.field("original_lot_id",s.original_lot_id);a.field("recipient_lot_id",s.recipient_lot_id);a.field("from_inventory_id",s.from_inventory_id);a.field("to_inventory_id",s.to_inventory_id);a.field("tick",s.tick);return a.optional("actual_result",s.actual_result,[](auto& c,auto& v){return result(c,v);});}
template<class A>Status report_start(A& a,TaskMessageReturnReportStart& s){if(s.context.kind||s.context.encounter_id||s.context.input_error)return a.reject("UnsupportedTaskMessageReturnContext");a.field("fact_id",s.fact_id);a.field("task_id",s.task_id);a.field("collection_fact_id",s.collection_fact_id);a.field("action_id",s.action_id);a.field("original_lot_id",s.original_lot_id);a.field("from_inventory_id",s.from_inventory_id);a.field("to_inventory_id",s.to_inventory_id);a.field("carrier_actor_id",s.carrier_actor_id);a.field("sender_actor_id",s.sender_actor_id);a.field("session_id",s.session_id);a.field("dialogue_id",s.dialogue_id);a.field("node_id",s.node_id);a.object("context",[&](auto& c){c.field("place_id",s.context.place_id);c.field("provider_actor_id",s.context.provider_actor_id);return c.field("role_id",s.context.role_id);});a.field("started_tick",s.started_tick);return a.optional("actual_result",s.actual_result,[](auto& c,auto& v){return result(c,v);});}
template<class A>Status report_interruption(A& a,TaskMessageReturnReportInterruption& s){a.field("fact_id",s.fact_id);a.field("report_start_fact_id",s.report_start_fact_id);a.field("task_id",s.task_id);a.field("action_id",s.action_id);a.field("reason",s.reason);a.field("tick",s.tick);a.field("effect_task_id_present",s.effect_task_id_present);a.optional("on_unavailable",s.on_unavailable,[](auto& c,auto& v){return c.field("value",v);});a.optional("retry",s.retry,[](auto& c,auto& v){return c.field("value",v);});return a.optional("actual_result",s.actual_result,[](auto& c,auto& v){return result(c,v);});}
template<class A>Status state(A& a,TaskMessageReturnState& s){a.field("version",s.version);if(s.version!=1)return a.reject("UnsupportedTaskMessageReturnVersion");dynamic_codec::table(a,"starts",s.starts,[](auto& c,auto& v){return start(c,v);});dynamic_codec::table(a,"collections",s.collections,[](auto& c,auto& v){return collection(c,v);});dynamic_codec::table(a,"deliveries",s.deliveries,[](auto& c,auto& v){return delivery(c,v);});dynamic_codec::table(a,"report_starts",s.report_starts,[](auto& c,auto& v){return report_start(c,v);});return dynamic_codec::table(a,"report_interruptions",s.report_interruptions,[](auto& c,auto& v){return report_interruption(c,v);});}
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("TaskMessageReturnTooDeep");if(const auto* d=v.as<BoundaryValue::Dict>()){if(d->size()>CodecVisitor::max_items)return common_failure("TaskMessageReturnTooLarge");std::set<StableId> seen;for(const auto& row:*d){if(!seen.insert(row.first).second)return common_failure("DuplicateTaskMessageReturnField",row.first);auto r=unique(row.second,depth+1);if(!r.ok)return r;}}if(const auto* a=v.as<BoundaryValue::Array>()){if(a->size()>CodecVisitor::max_items)return common_failure("TaskMessageReturnTooLarge");for(const auto& row:*a){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
Status emit_task_message_returns_fields(ProjectionWriter&w,const TaskMessageReturnState&v){dynamic_projection::Archive a(w);return state(a,const_cast<TaskMessageReturnState&>(v));}
BoundaryValue encode_task_message_returns(const TaskMessageReturnState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_message_returns_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Outcome<TaskMessageReturnState> decode_task_message_returns(const BoundaryValue& v){auto r=unique(v);if(!r.ok)return {false,{},r.error};TaskMessageReturnState s;dynamic_codec::JsonArchive a(v);r=state(a,s);if(r.ok)r=a.finish();return r.ok?Outcome<TaskMessageReturnState>{true,std::move(s),{}}:Outcome<TaskMessageReturnState>{false,{},r.error};}
Status visit_task_message_returns_checkpoint(CodecVisitor& a,TaskMessageReturnState& s){return state(a,s);}
Status emit_task_message_return_fact_fields(ProjectionWriter&w,const TaskMessageReturnState&s,const StableId&id){dynamic_projection::Archive a(w);Status valid;if(const auto*row=s.starts.find(id)){valid=start(a,const_cast<TaskMessageReturnStart&>(*row));}else if(const auto*row=s.collections.find(id)){valid=collection(a,const_cast<TaskMessageReturnCollection&>(*row));}else if(const auto*row=s.deliveries.find(id)){valid=delivery(a,const_cast<TaskMessageReturnDelivery&>(*row));}else if(const auto*row=s.report_starts.find(id)){valid=report_start(a,const_cast<TaskMessageReturnReportStart&>(*row));}else if(const auto*row=s.report_interruptions.find(id)){valid=report_interruption(a,const_cast<TaskMessageReturnReportInterruption&>(*row));}else return common_failure("TaskMessageReturnSourceMissing",id);if(!valid.ok)return valid;return w.status();}
Outcome<BoundaryValue> encode_task_message_return_fact(const TaskMessageReturnState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_message_return_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
